// src/post_llm_validator.js
console.log("[PostLLMValidator] Starting Guard-Rail validation...");

// 1. Get the tiny decisions array from the LLM
let llm_decisions = items[0].json.decisions || [];

// 2. Get the heavy raw data from the Pre-Parser
let rows_parsed = [];
let meta = {};
try {
    const preParserData = $('Pre-Parser').first().json;
    rows_parsed = preParserData.rows_parsed || [];
    meta = {
        email_emetteur: preParserData.email_emetteur || "unknown",
        fichier_source: preParserData.fichier_source || "unknown",
        db_ids: preParserData.db_ids || []
    };
} catch(e) {
    console.log("[PostLLMValidator] Error fetching Pre-Parser data.");
}

// 3. Fallback Regex Safety Net
const REGEX = {
    montant: /^\d{1,6},\d{2}$/,
    date_vir: /^\d{8}$/,
    date_soin: /^\d{8}$/,
    email: /^[^\s@]+@[^\s@]+\.[^\s@]+$/
};
const VALID_CODE_ACTE = ['C', 'CS', 'V', 'AIS', 'AMK', 'AMI', 'BSB'];

const rows_valides = [];
const rows_rejetees = [];
const psRejetMap = {};

for (let i = 0; i < rows_parsed.length; i++) {
    const row = rows_parsed[i];
    const ps = row.num_ps;
    const llm = llm_decisions[i] || {}; // Get the LLM's opinion for this specific row

    // Contagion: if PS already rejected, reject all its lines
    if (psRejetMap[ps]) {
        row.raison_rejet = psRejetMap[ps];
        row.llm_decision = "CONTAGION";
        rows_rejetees.push(row);
        continue;
    }

    let raison = null;

    // A. Listen to the LLM (Semantic validation)
    if (llm.is_valid === false) {
        raison = llm.anomalie_semantique || "ANOMALIE_DETECTEE_PAR_IA";
    }

    // B. Guard-Rail (Deterministic format validation)
    if (!raison) {
        if (!row.num_ps || String(row.num_ps).trim() === "") raison = "CHAMP_MANQUANT";
        else if (!REGEX.montant.test(row.montant)) raison = "FORMAT_MONTANT_INVALIDE";
        else if (!REGEX.email.test(row.email)) raison = "FORMAT_EMAIL_INVALIDE";
        else if (!VALID_CODE_ACTE.includes(row.code_acte)) raison = "CODE_ACTE_INCONNU";
    }

    if (raison) {
        psRejetMap[ps] = raison;
        row.raison_rejet = raison;
        row.llm_decision = (llm.is_valid === false) ? "LLM_REJECT" : "REGEX_REJECT";
        rows_rejetees.push(row);
    } else {
        row.llm_decision = "VALID";
        rows_valides.push(row);
    }
}

const ps_valides = [...new Set(rows_valides.map(r => r.num_ps))];
const ps_rejetes = Object.keys(psRejetMap);

const items_to_return = [];

// 1. Create a clean "VALID" item
if (rows_valides.length > 0) {
    items_to_return.push({
        json: {
            type: "VALID",
            rows_valides: rows_valides,
            ps_valides: ps_valides,
            ...meta
        }
    });
}

// 2. Create a clean "REJET" item
if (rows_rejetees.length > 0) {
    items_to_return.push({
        json: {
            type: "REJET",
            rows_rejetees: rows_rejetees,
            ps_rejetes: ps_rejetes,
            ...meta
        }
    });
}

// Return the items to the next node
return items_to_return;

if (!items || items.length === 0) return [];
let mergedContent = '';
const ids = [];
for (const item of items) {
  mergedContent += item.json.contenu + '\n';
  ids.push(item.json.id);
}
return [{ json: {
  fileContent: mergedContent,
  fileName: 'batch_db_' + ids.join('_') + '.ok',
  db_ids: ids
}}];

console.log("Starting Pre-Parser node...");

const inputJson = items[0].json;
const fileContent = inputJson.fileContent || inputJson.contenu;

if (!fileContent) {
    console.log("Error: No file content provided");
    return [{ json: { error: "No file content" } }];
}

const lines = fileContent.split('\n');
const rows_parsed = [];

for (let line of lines) {
    line = line.trim();
    const cols = line.split('|').map(c => c.trim());

    if (cols.length >= 14 && cols[1].match(/^\d{9}$/)) {
        rows_parsed.push({
            num_ps: cols[1],
            email: cols[2],
            bic: cols[3],
            iban: cols[4],
            intitule: cols[5],
            montant: cols[6],
            date_vir: cols[7],
            numvir: cols[8],
            code_acte: cols[9],
            specialite: cols[10],
            region: cols[11],
            date_soin: cols[12],
            nb_actes: cols[13]
        });
    }
}

console.log(`Parsed ${rows_parsed.length} rows.`);

return [{
    json: {
        fichier_source: inputJson.fileName || inputJson.nom_fichier || "inconnu",
        rows_parsed: rows_parsed,
        db_ids: inputJson.db_ids || []
    }
}];

